UPDATE user_profile
SET access_token = #{accessToken},
    refresh_token = #{refreshToken},
    access_token_expires_at = #{accessTokenExpiresAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{profileId}
  AND deleted_at IS NULL

UPDATE user_profile
SET access_token = #{accessToken},
    access_token_expires_at = #{accessTokenExpiresAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{profileId}
  AND deleted_at IS NULL

UPDATE user_profile
SET last_login_at = #{lastLoginAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{profileId}
  AND deleted_at IS NULL

UPDATE user_profile
SET last_logout_at = #{lastLogoutAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{profileId}
  AND deleted_at IS NULL
